import { fmt, n, q, num, L, U } from "./ee-shape.mjs";

const uLine = 230;
const zLoop = 2;
const iFault = uLine / zLoop;
const rPe = 0.2;
const vTouch = iFault * rPe;
const vClass = 50;
const rPeMax = vClass / iFault;
const iHeat = 10;
const rWire = 0.2;
const pHeat = iHeat * iHeat * rWire;
const iWeak = uLine / 50;

const iLoad = 20;
const rLine = 0.3;
const drop1 = iLoad * rLine;
const vRecv = 230 - drop1;
const drop3 = Math.sqrt(3) * iLoad * rLine;
const pct3 = drop3 / 400;
const dropNeutral = iLoad * (rLine + rLine);

const pCoil = 5;
const vCoil = 24;
const iCoil = pCoil / vCoil;
const rCoil = (vCoil * vCoil) / pCoil;
const iSealRatio = 8;
const iInrush = iSealRatio * iCoil;
const fla = 10;
const startMul = 6;
const iStart = startMul * fla;
const vSag = 18;
const pSag = pCoil * (vSag / vCoil) ** 2;

